solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <map>
#include <optional>
#include <set>
#include <utility>
#include <vector>

enum class Op { Plain, Call, Jump, Branch, Return };
struct Insn { std::uint32_t address; std::uint32_t length; Op op; std::uint32_t target; };
struct Block { std::uint32_t start; std::uint32_t end; std::vector<std::uint32_t> successors; };
struct Loop { std::uint32_t header; std::vector<std::uint32_t> body; };

class Graph
{
public:
    explicit Graph(const std::vector<Insn>& code)
    {
        if (code.empty()) return;
        std::set<std::uint32_t> addresses;
        for (const Insn& i : code) addresses.insert(i.address);
        std::set<std::uint32_t> leaders{ code.front().address };
        for (std::size_t k{ 0 }; k < code.size(); ++k)
        {
            const Insn& i{ code[k] };
            if ((i.op == Op::Jump || i.op == Op::Branch) && addresses.count(i.target)) leaders.insert(i.target);
            if ((i.op == Op::Jump || i.op == Op::Branch || i.op == Op::Return) && k + 1 < code.size()) leaders.insert(code[k + 1].address);
        }
        for (std::size_t k{ 0 }; k < code.size(); ++k)
        {
            if (leaders.count(code[k].address)) list.push_back({ code[k].address, 0, {} });
            const Insn& i{ code[k] };
            Block& b{ list.back() };
            b.end = i.address + i.length;
            if (k + 1 < code.size() && !leaders.count(code[k + 1].address)) continue;
            std::set<std::uint32_t> next;
            if (i.op != Op::Jump && i.op != Op::Return && k + 1 < code.size()) next.insert(code[k + 1].address);
            if ((i.op == Op::Jump || i.op == Op::Branch) && addresses.count(i.target)) next.insert(i.target);
            b.successors.assign(next.begin(), next.end());
        }
    }

    const std::vector<Block>& blocks() const { return list; }

    std::optional<std::uint32_t> blockOf(std::uint32_t address) const
    {
        for (const Block& b : list) if (address >= b.start && address < b.end) return b.start;
        return std::nullopt;
    }

    std::vector<std::uint32_t> predecessors(std::uint32_t block) const
    {
        std::vector<std::uint32_t> out;
        for (const Block& b : list)
            if (std::find(b.successors.begin(), b.successors.end(), block) != b.successors.end()) out.push_back(b.start);
        return out;
    }

    std::vector<std::uint32_t> unreachable() const
    {
        if (list.empty()) return {};
        std::set<std::uint32_t> seen{ list.front().start };
        std::vector<std::uint32_t> work{ list.front().start };
        while (!work.empty())
        {
            const std::uint32_t at{ work.back() };
            work.pop_back();
            for (std::uint32_t s : find(at).successors)
                if (seen.insert(s).second) work.push_back(s);
        }
        std::vector<std::uint32_t> out;
        for (const Block& b : list) if (!seen.count(b.start)) out.push_back(b.start);
        return out;
    }

    std::vector<std::pair<std::uint32_t, std::uint32_t>> backEdges() const
    {
        std::vector<std::pair<std::uint32_t, std::uint32_t>> out;
        for (const Block& b : list)
            for (std::uint32_t s : b.successors)
                if (s <= b.start) out.push_back({ b.start, s });
        std::sort(out.begin(), out.end());
        return out;
    }

    std::vector<Loop> loops() const
    {
        std::map<std::uint32_t, std::set<std::uint32_t>> bodies;
        for (const auto& [from, header] : backEdges())
        {
            std::set<std::uint32_t>& body{ bodies[header] };
            body.insert(header);
            std::vector<std::uint32_t> work;
            if (body.insert(from).second) work.push_back(from);
            while (!work.empty())
            {
                const std::uint32_t at{ work.back() };
                work.pop_back();
                for (std::uint32_t p : predecessors(at))
                    if (body.insert(p).second) work.push_back(p);
            }
        }
        std::vector<Loop> out;
        for (const auto& [header, body] : bodies) out.push_back({ header, { body.begin(), body.end() } });
        return out;
    }

private:
    std::vector<Block> list;

    const Block& find(std::uint32_t start) const
    {
        for (const Block& b : list) if (b.start == start) return b;
        return list.front();
    }
};

unitTests:
using U = std::vector<std::uint32_t>;
using Edges = std::vector<std::pair<std::uint32_t, std::uint32_t>>;
// Two nested loops:
//   for (i...) { for (j...) { ... } if (x) continue; ... }   plus dead code after the return.
static std::vector<Insn> nested()
{
    return {
        { 0x00, 2, Op::Plain, 0 },        // A: setup
        { 0x02, 2, Op::Plain, 0 },        // B: outer top
        { 0x04, 2, Op::Plain, 0 },        // C: inner top
        { 0x06, 2, Op::Branch, 0x04 },    //    jl inner top
        { 0x08, 2, Op::Branch, 0x02 },    // D: if (x) continue -> outer top
        { 0x0A, 5, Op::Call, 0x9000 },    // E: call something
        { 0x0F, 2, Op::Branch, 0x02 },    //    jl outer top
        { 0x11, 1, Op::Return, 0 },       // F: ret
        { 0x12, 2, Op::Plain, 0 },        // G: dead code
        { 0x14, 1, Op::Return, 0 },
    };
}

TEST("blocks and lookups") {
    Graph g{ nested() };
    CHECK_EQ(g.blocks().size(), 7u);
    CHECK_EQ(g.blockOf(0x06).value_or(99), 0x04u);
    CHECK_EQ(g.blockOf(0x0C).value_or(99), 0x0Au);
    CHECK(!g.blockOf(0x40).has_value());
    CHECK_EQ(g.predecessors(0x02), (U{ 0x00, 0x08, 0x0A }));
    CHECK_EQ(g.predecessors(0x04), (U{ 0x02, 0x04 }));
}
TEST("unreachable code") {
    Graph g{ nested() };
    CHECK_EQ(g.unreachable(), (U{ 0x12 }));
}
TEST("back edges") {
    Graph g{ nested() };
    CHECK_EQ(g.backEdges(), (Edges{ { 0x04, 0x04 }, { 0x08, 0x02 }, { 0x0A, 0x02 } }));
}
TEST("natural loops") {
    Graph g{ nested() };
    const auto loops{ g.loops() };
    CHECK_EQ(loops.size(), 2u);
    if (loops.size() != 2) return;
    CHECK_EQ(loops[0].header, 0x02u);
    CHECK_EQ(loops[0].body, (U{ 0x02, 0x04, 0x08, 0x0A }));
    CHECK_EQ(loops[1].header, 0x04u);
    CHECK_EQ(loops[1].body, (U{ 0x04 }));
}
TEST("no code, no loops") {
    Graph g{ {} };
    CHECK(g.blocks().empty());
    CHECK(g.unreachable().empty());
    CHECK(g.backEdges().empty());
    CHECK(g.loops().empty());
    Graph straight{ { { 0, 1, Op::Plain, 0 }, { 1, 1, Op::Return, 0 } } };
    CHECK_EQ(straight.blocks().size(), 1u);
    CHECK(straight.loops().empty());
}

